package com.aistock.notification.alert;
import com.aistock.common.BusinessException;import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.*;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.flywaydb.core.Flyway;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@Tag("mysql") class AlertEvaluationMysqlTest {
 JdbcTemplate jdbc;AlertRuleService rules;AlertEvaluationService service;AlertEvidenceClient market;AlertMailAccountClient accounts;AlertEvidenceClient.Evidence evidence;UUID owner=UUID.randomUUID();Clock clock;AlertRecords.Rule rule;
 @BeforeEach void setup()throws Exception{
  var mapper=new ObjectMapper().findAndRegisterModules();evidence=mapper.readValue(getClass().getResourceAsStream("/alert/evidence.json"),AlertEvidenceClient.Evidence.class);clock=Clock.fixed(evidence.capturedAt().plusSeconds(1),ZoneOffset.UTC);
  String url=System.getenv("MAIL_TEST_DB_URL"),pw=System.getenv("MAIL_TEST_DB_PASSWORD");if(!"jdbc:mysql://127.0.0.1:13316/stock_notification_test?serverTimezone=UTC".equals(url)||pw==null)throw new IllegalStateException("isolated DB required");jdbc=new JdbcTemplate(new DriverManagerDataSource(url,"root",pw));Flyway.configure().dataSource(jdbc.getDataSource()).load().migrate();var repo=new AlertRuleRepository(jdbc);
  rules=new AlertRuleService(repo,id->boundary(evidence.tradeDate().minusDays(1)),clock,50);rule=rules.create(owner,new AlertRecords.Create(UUID.randomUUID(),"SH600030","PRICE_ABOVE","25.90"));
  market=mock(AlertEvidenceClient.class);accounts=mock(AlertMailAccountClient.class);when(market.read(evidence.id())).thenReturn(evidence);when(market.boundary("SH600030")).thenReturn(boundary(evidence.tradeDate()));when(accounts.context(owner)).thenReturn(new AlertMailAccountClient.AccountContext(owner,"ENABLED",7,true,clock.instant()));service=new AlertEvaluationService(repo,market,accounts,new com.aistock.notification.alertmail.AlertMailOutbox(new com.aistock.notification.alertmail.AlertMailRepository(jdbc),false,java.time.Duration.ofHours(24)),clock);
 }
 AlertRecords.Boundary boundary(LocalDate day){return new AlertRecords.Boundary("SH600030","baostock",evidence.rawVersionId(),day,day,day,"a".repeat(64),clock.instant(),"alert-boundary-v1");}
 AlertEvaluationRecords.EvaluateRequest request(){return new AlertEvaluationRecords.EvaluateRequest(UUID.randomUUID(),rule.id(),rule.revision(),evidence.id(),clock.instant().plusSeconds(90));}
 int triggers(){return jdbc.queryForObject("select count(*) from alert_trigger where owner_id=?",Integer.class,owner.toString());}int messages(){return jdbc.queryForObject("select count(*) from inbox_message where owner_id=?",Integer.class,owner.toString());}
 @Test void savesTriggerMessageAndReceiptExactlyOnceAndRejectsOperationConflict(){var r=request();var first=service.evaluate(r);assertEquals("TRIGGERED",first.state());assertEquals(first,service.evaluate(r));assertEquals(first,service.receipt(r.operationId()));assertEquals(1,triggers());assertEquals(1,messages());assertEquals("ALERT_OPERATION_CONFLICT",assertThrows(BusinessException.class,()->service.evaluate(new AlertEvaluationRecords.EvaluateRequest(r.operationId(),r.ruleId(),r.revision(),UUID.randomUUID(),r.leaseUntil()))).code());verify(market,times(1)).read(evidence.id());}
 @Test void twoConcurrentOperationsForSameDayHaveOnlyOneMessage()throws Exception{var pool=Executors.newFixedThreadPool(2);try{var results=pool.invokeAll(List.<Callable<AlertEvaluationRecords.EvaluationReceipt>>of(()->service.evaluate(request()),()->service.evaluate(request())));var states=new HashSet<String>();for(var result:results)states.add(result.get().state());assertEquals(Set.of("TRIGGERED","ALREADY_TRIGGERED"),states);assertEquals(1,triggers());assertEquals(1,messages());}finally{pool.shutdownNow();}}
 @Test void exposesCheckForTheOwnedCurrentRevisionWithVerifiedDate(){
  rule=rules.patch(owner,rule.id(),new AlertRecords.Patch(0L,null,"25.91",null));
  assertEquals("NOT_MET",service.evaluate(request()).state());
  var check=rules.list(owner,1,20).recentChecks().get(rule.id());
  assertNotNull(check);
  assertEquals("NOT_MET",check.state());
  assertEquals(evidence.tradeDate(),check.tradeDate());
  assertEquals(clock.instant().truncatedTo(java.time.temporal.ChronoUnit.MICROS),check.checkedAt());
  assertTrue(rules.list(UUID.randomUUID(),1,20).recentChecks().isEmpty());
  rule=rules.patch(owner,rule.id(),new AlertRecords.Patch(rule.revision(),null,null,false));
  assertFalse(rules.list(owner,1,20).recentChecks().containsKey(rule.id()));
 }
 @Test void equalityIsNotMet(){rule=rules.patch(owner,rule.id(),new AlertRecords.Patch(0L,null,"25.91",null));assertEquals("NOT_MET",service.evaluate(request()).state());assertEquals(0,messages());}
 @Test void disabledAccountDoesNotTriggerAndDependencyFailureIsRecoverable(){when(accounts.context(owner)).thenReturn(new AlertMailAccountClient.AccountContext(owner,"DISABLED",7,true,clock.instant()));assertEquals("SKIPPED_INACTIVE",service.evaluate(request()).state());assertEquals(0,messages());when(accounts.context(owner)).thenThrow(AlertRemoteHttp.unavailable());assertEquals("FAILED",service.evaluate(request()).state());assertEquals(0,triggers());}
 @Test void ruleRevisionChangeDuringExternalReadPreventsTrigger(){var r=request();when(market.read(evidence.id())).thenAnswer(call->{rules.patch(owner,rule.id(),new AlertRecords.Patch(0L,null,null,false));return evidence;});assertEquals("SKIPPED_RULE_CHANGED",service.evaluate(r).state());assertEquals(0,messages());}
 @Test void staleRawEvidenceAndExpiredLeaseCannotTrigger(){when(market.boundary("SH600030")).thenReturn(new AlertRecords.Boundary("SH600030","baostock",UUID.randomUUID(),evidence.tradeDate(),evidence.tradeDate(),evidence.tradeDate(),"a".repeat(64),clock.instant(),"alert-boundary-v1"));assertEquals("SKIPPED_STALE",service.evaluate(request()).state());var r=request();assertEquals("FAILED",service.evaluate(new AlertEvaluationRecords.EvaluateRequest(r.operationId(),r.ruleId(),r.revision(),r.evidenceId(),clock.instant().minusSeconds(1))).state());assertEquals(0,messages());}
 @Test void newRuleEffectiveOnCurrentDayDoesNotBackfill(){var sameDayRules=new AlertRuleService(new AlertRuleRepository(jdbc),id->boundary(evidence.tradeDate()),clock,50);rule=sameDayRules.create(owner,new AlertRecords.Create(UUID.randomUUID(),"SH600030","PRICE_ABOVE","25"));assertEquals("SKIPPED_NOT_EFFECTIVE",service.evaluate(request()).state());assertEquals(0,messages());}
 @Test void paginationIsMonotonicAndOwnerComesFromStoredRule(){var page=service.due(null,1,"SH600030");assertTrue(page.items().size()<=1);if(page.nextCursor()!=null){var next=service.due(page.nextCursor(),50,"SH600030");assertTrue(next.items().stream().allMatch(i->i.ruleId().toString().compareTo(page.nextCursor())>0));}assertThrows(BusinessException.class,()->service.due("bad",50,null));}
 @Test void sameOperationInFlightReturnsRunningWithoutSecondDispatch()throws Exception{
  var request=request();var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var calls=new java.util.concurrent.atomic.AtomicInteger();when(market.read(evidence.id())).thenAnswer(call->{if(calls.incrementAndGet()==1){entered.countDown();assertTrue(release.await(5,TimeUnit.SECONDS));}return evidence;});var pool=Executors.newSingleThreadExecutor();var first=pool.submit(()->service.evaluate(request));
  try{assertTrue(entered.await(3,TimeUnit.SECONDS));assertEquals("RUNNING",service.evaluate(request).state());assertEquals(1,calls.get());}finally{release.countDown();first.get(5,TimeUnit.SECONDS);pool.shutdownNow();}
 }
 @Test void messageInsertFailureRollsBackTriggerButPreservesFailedReceipt(){
  String name="fail_inbox_"+UUID.randomUUID().toString().replace("-","");jdbc.execute("CREATE TRIGGER "+name+" BEFORE INSERT ON inbox_message FOR EACH ROW BEGIN IF NEW.owner_id = '"+owner+"' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fixture forced inbox failure'; END IF; END");
  try{var result=service.evaluate(request());assertEquals("FAILED",result.state());assertEquals(0,triggers());assertEquals(0,messages());assertEquals(result,service.receipt(result.operationId()));}finally{jdbc.execute("DROP TRIGGER "+name);}
 }
 @Test void missingComparableSourceStillAllowsPriceButNotDailyRate()throws Exception{
  var mapper=new ObjectMapper().findAndRegisterModules();var tree=(com.fasterxml.jackson.databind.node.ObjectNode)mapper.valueToTree(evidence);tree.put("changeState","SOURCE_UNAVAILABLE");tree.putNull("previousBackwardClose");tree.putNull("currentBackwardClose");tree.putNull("sourcePayloadHash");var unavailable=mapper.treeToValue(tree,AlertEvidenceClient.Evidence.class);when(market.read(evidence.id())).thenReturn(unavailable);
  assertEquals("TRIGGERED",service.evaluate(request()).state());rule=rules.create(owner,new AlertRecords.Create(UUID.randomUUID(),"SH600030","DAILY_RISE","2"));assertEquals("EVIDENCE_UNAVAILABLE",service.evaluate(request()).state());assertEquals(1,messages());
 }
 @Test void crossingDailyCutoffRequiresFreshBoundary(){
  var time=new java.util.concurrent.atomic.AtomicReference<>(Instant.parse("2026-10-10T11:59:59Z"));clock=new Clock(){public java.time.ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(java.time.ZoneId zone){return Clock.fixed(time.get(),zone);}public Instant instant(){return time.get();}};service=new AlertEvaluationService(new AlertRuleRepository(jdbc),market,accounts,new com.aistock.notification.alertmail.AlertMailOutbox(new com.aistock.notification.alertmail.AlertMailRepository(jdbc),false,java.time.Duration.ofHours(24)),clock);when(market.boundary("SH600030")).thenReturn(boundary(evidence.tradeDate()));when(accounts.context(owner)).thenAnswer(call->{time.set(time.get().plusSeconds(2));return new AlertMailAccountClient.AccountContext(owner,"ENABLED",7,true,clock.instant());});
  var result=service.evaluate(request());assertEquals("FAILED",result.state());assertEquals("ALERT_BOUNDARY_CHANGED",result.reasonCode());assertEquals(0,messages());
 }
 @Test void extremelyOldLeaseIsRejectedBeforeDatabaseTimestampConversion(){var r=request();assertEquals("VALIDATION_FAILED",assertThrows(BusinessException.class,()->service.evaluate(new AlertEvaluationRecords.EvaluateRequest(r.operationId(),r.ruleId(),r.revision(),r.evidenceId(),Instant.parse("1900-01-01T00:00:00Z")))).code());}
 @Test void everyNewTriggerAlsoCommitsOneMailChannelDecision(){var r=request();var first=service.evaluate(r);assertEquals("TRIGGERED",first.state());assertEquals("ALREADY_TRIGGERED",service.evaluate(request()).state());assertEquals(1,jdbc.queryForObject("select count(*) from alert_mail_delivery where trigger_id=?",Integer.class,first.triggerId().toString()));}
 @Test void outboxFailureRollsBackTriggerAndMessageAndSavesFailedReceipt(){String name="fail_mail_eval_"+owner.toString().replace("-","");jdbc.execute("CREATE TRIGGER "+name+" BEFORE INSERT ON alert_mail_delivery FOR EACH ROW BEGIN IF NEW.owner_id='"+owner+"' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='fixture reject'; END IF; END");try{var r=request();assertEquals("FAILED",service.evaluate(r).state());assertEquals(0,triggers());assertEquals(0,messages());assertEquals("FAILED",service.receipt(r.operationId()).state());}finally{jdbc.execute("DROP TRIGGER "+name);}}}
